def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    flat = Counter(c for row in grid for c in row)
    bg = flat.most_common(1)[0][0]

    # find barrier: full row or column of 2s
    barrier = None  # ('h', row) or ('v', col)
    for r in range(H):
        if all(grid[r][c] == 2 for c in range(W)):
            barrier = ('h', r); break
    if barrier is None:
        for c in range(W):
            if all(grid[r][c] == 2 for r in range(H)):
                barrier = ('v', c); break

    out = [row[:] for row in grid]
    cells = [(r, c, grid[r][c]) for r in range(H) for c in range(W)
             if grid[r][c] != bg and grid[r][c] != 2]
    color = cells[0][2]

    if barrier[0] == 'h':
        b = barrier[1]
        rs = [r for r, c, v in cells]
        if max(rs) < b:
            gap = b - max(rs) - 1
            dr = gap
        else:
            gap = min(rs) - b - 1
            dr = -gap
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r + dr][c] = v
        if dr >= 0:
            line = min(rs) + dr - 1
        else:
            line = max(rs) + dr + 1
        for c in range(W):
            out[line][c] = 8
    else:
        b = barrier[1]
        cs = [c for r, c, v in cells]
        if max(cs) < b:
            gap = b - max(cs) - 1
            dc = gap
        else:
            gap = min(cs) - b - 1
            dc = -gap
        for r, c, v in cells:
            out[r][c] = bg
        for r, c, v in cells:
            out[r][c + dc] = v
        if dc >= 0:
            line = min(cs) + dc - 1
        else:
            line = max(cs) + dc + 1
        for r in range(H):
            out[r][line] = 8
    return out
